(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03-t*0.15)*8 + Math.cos(sy*0.025+t*0.2)*6;
  const w2y = Math.cos(sy*0.03+t*0.18)*8 + Math.sin(sx*0.028-t*0.22)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.14, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*55, 0.11, 1.8],
    [200+Math.sin(t*0.7+1)*90, 220+Math.cos(t*0.5+3)*40, 0.05, 2.4],
    [300+Math.cos(t*0.4+4)*80, 30+Math.sin(t*0.6+2)*60, 0.13, 2.0]
  ];
  let aS=0, iS=0, hrm=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hrm += Math.cos(d*f*1.3-t*sp*0.8+2.0);
  }
  const act=aS/10, inh=iS/10, hr=hrm/10;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1)+Math.sin(dx*0.05+dy*0.01-t*0.6))/3
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((dx-cx)**2+(dy-cy)**2), ang = Math.atan2(dy-cy,dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.9))*0.33;
  const hex = Math.sin(dx*0.12)*Math.sin(dy*0.12)+Math.sin((dx+dy*0.577)*0.1+t*0.7)+Math.sin((dx-dy*0.577)*0.1-t*0.5);
  const micro = Math.sin(dx*0.25+t*3)*Math.sin(dy*0.25-t*2.5)*0.15;
  const r1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2 = Math.tanh((hr*0.5+r1*0.8+hex*0.2+micro)*2.0);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = r2*0.6+cell*0.2+spiral*0.2, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,45,95],[18,85,125],[25,135,140],[60,170,130],[140,195,100],[210,190,60],[230,150,55],[220,100,65],[185,60,70],[140,35,65],[90,18,55],[40,10,50],[5,12,55]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(r2*Math.PI)*0.2, edge=Math.abs(r2)>0.7?1.15:1.0;
  const glow=Math.exp(-dist*0.003)*0.1;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0
  ];
}
